defectIntroducedWI.pseudoCode:
let defectWI = response.defectIntroducedWI;
if (!defectWI && response.relatedWorkitems) {
  const introduced = response.relatedWorkitems.find(wi => wi.relationshipType === 'introduced-by');
  defectWI = introduced?.workItemId;
}

